/* These functions have no DOM dependency and are also tested against independent circuit arithmetic. */
const FOUNDATION_MODELS9={
 divider(p){const r=p.r.slice(0,p.count).map(x=>x*1000),tap=Math.max(1,Math.min(p.count-1,p.tap)),up=r.slice(0,tap).reduce((a,b)=>a+b,0),down=r.slice(tap).reduce((a,b)=>a+b,0),load=p.load*1000,eq=p.loaded?down*load/(down+load):down,Iup=p.v/(up+eq),v=Iup*eq,Idown=v/down,Iload=p.loaded?v/load:0,nodes=[p.v];for(let i=0;i<r.length;i++)nodes.push(nodes[i]-(i<tap?Iup:Idown)*r[i]);nodes[nodes.length-1]=0;return{up,down,eq,Iup,Idown,Iload,v,nodes,noLoad:p.v*down/(up+down),drops:r.map((x,i)=>x*(i<tap?Iup:Idown))};},
 rc(p,x,dt=0){const R=p.r*1000,C=p.c*1e-6,tau=R*C,target=p.on?p.v:0,value=target+(x-target)*Math.exp(-Math.max(0,dt)/tau);return{value,tau,target,current:(target-value)/R,energy:.5*C*value*value,charge:C*value};},
 rl(p,x,dt=0){const R=p.r+p.rw,L=p.l/1000,tau=L/R,source=p.on?p.v:0,target=source/R,value=target+(x-target)*Math.exp(-Math.max(0,dt)/tau),voltage=source-R*value;return{value,tau,target,current:value,voltage,coilVoltage:voltage+p.rw*value,energy:.5*L*value*value};}
};

