 function mount(container,id){unmount();mounted=container;if(!mounted)return;state(id).message='';abort=new AbortController();const opts={signal:abort.signal};
 mounted.addEventListener('input',e=>{const el=e.target,k=el.dataset.f9Param;if(!k)return;const s=state(id),p=s.p,value=el.type==='checkbox'?el.checked:Number(el.value);if(!Number.isFinite(value)&&typeof value!=='boolean')return;if(/^r\d$/.test(k))p.r[+k[1]]=value;else p[k]=value;if(k==='count'){p.tap=Math.min(p.tap,p.count-1);rebuildControls();}if(s.kind!=='divider'&&k!=='speed')reset();mounted.querySelectorAll('[data-f9-read]').forEach(o=>{const key=o.dataset.f9Read,input=mounted.querySelector(`[data-f9-param="${key}"]`);if(input){const unit=o.textContent.split(' ').slice(-1)[0];o.textContent=fmt(+input.value)+' '+unit;}});paint();},opts);
 mounted.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const s=state(id),a=b.dataset.f9Action,preset=b.dataset.f9Preset;if(preset){const values={two:{v:6,count:2,r:[1,1,1],tap:1,loaded:false,load:1},three:{v:9,count:3,r:[1,1,1],tap:1,loaded:false,load:1},unequal:{v:12,count:3,r:[1,2,3],tap:1,loaded:false,load:3},loaded:{v:10,count:2,r:[1,1,1],tap:1,loaded:true,load:1}};Object.assign(s.p,values[preset]);rebuildControls();paint();return;}if(a==='start'){if(!s.run){s.run=true;s.message=T('正在播放；曲线横轴始终是物理时间。','Playing; the horizontal axis always shows physical time.');last=0;raf=requestAnimationFrame(frame);paint();}}if(a==='pause')pause();if(a==='reset')reset();if(a==='step'){pause();advance(s,result(s).tau);s.message=T('已按当前回路前进一个时间常数。','Advanced one time constant of the current circuit.');paint();}if(a==='mode'){s.p.on=!s.p.on;s.message=T('已切换回路，保留切换瞬间的状态。','Circuit switched while preserving the instantaneous state.');paint();}},opts);paint();}
 function getDraft(id,q){return window.ZTHProgress9?.getDraft(id,q)?.value??localDrafts.get(id+'/'+q);}
 function attempts(id,q){return window.ZTHProgress9?.getAttempts(id,q)||localAttempts.get(id+'/'+q)||[];}
 function questionMarkup(id,q,index){const draft=getDraft(id,q.id);return `<fieldset class="f9-question" data-f9-question="${q.id}"><legend><span>${String(index+1).padStart(2,'0')}</span>${h(tr(q.prompt))}</legend><div class="f9-options">${q.options.map(o=>`<label><input type="radio" name="${q.id}" value="${o.key}" ${draft===o.key?'checked':''}><b>${o.key}</b><span>${h(tr(o.label))}</span></label>`).join('')}</div><button data-f9-submit="${q.id}">${T('提交判断','Submit answer')}</button><div class="f9-feedback" data-f9-feedback role="status" aria-live="polite"></div><details class="f9-history"><summary>${T('历次判断记录','Attempt history')} <span data-f9-count>0</span></summary><ol data-f9-history></ol></details></fieldset>`;}
 function quizzes(id){return `<section class="f9-quiz" data-f9-quiz="${id}"><span class="eyebrow7">${T('可改答的练习','TRY, EXPLAIN, REVISE')}</span><h2>${T('选择后提交，看你的推理差在哪一步。','Submit a choice and check the reasoning.')}</h2><p>${T('每次提交分别记录。改答不会覆盖上次判断；下方历史可以回看。选择本身不是提交。','Every submission is recorded separately. Revising preserves previous attempts below. Selecting an option alone does not submit it.')}</p>${FOUNDATION_QUESTIONS9[id].map((q,i)=>questionMarkup(id,q,i)).join('')}</section>`;}
 function updateHistory(root,id,q){const list=attempts(id,q.id);root.querySelector('[data-f9-count]').textContent=String(list.length);root.querySelector('[data-f9-history]').innerHTML=list.map((a,i)=>{const option=q.options.find(o=>o.key===String(a.answer)),date=new Date(a.at);return `<li><span>${i+1} · ${Number.isFinite(date.getTime())?h(date.toLocaleString(UI4.lang==='en'?'en-GB':'zh-CN')):''}</span><b>${a.correct?T('正确','Correct'):T('需要修正','Needs revision')} · ${h(a.answer)} ${option?h(tr(option.label)):''}</b><p>${option?h(tr(option.feedback)):h(a.feedback||'')}</p></li>`;}).join('')||`<li>${T('还没有提交记录。','No attempts submitted yet.')}</li>`;}
 function mountQuiz(id){const node=document.querySelector(`[data-f9-quiz="${id}"]`);if(!node)return;for(const q of FOUNDATION_QUESTIONS9[id])updateHistory(node.querySelector(`[data-f9-question="${q.id}"]`),id,q);node.addEventListener('change',e=>{if(e.target.type!=='radio')return;const q=e.target.name;localDrafts.set(id+'/'+q,e.target.value);window.ZTHProgress9?.setDraft(id,q,e.target.value);},{signal:abort.signal});node.addEventListener('click',e=>{const button=e.target.closest('[data-f9-submit]');if(!button)return;const q=FOUNDATION_QUESTIONS9[id].find(q=>q.id===button.dataset.f9Submit),root=button.closest('fieldset'),value=root.querySelector('input:checked')?.value,feedback=root.querySelector('[data-f9-feedback]');if(!value){feedback.dataset.state='empty';feedback.textContent=T('先选择一个答案，再提交判断。','Select an answer before submitting.');return;}const option=q.options.find(o=>o.key===value),correct=q.correct===value,record={lessonId:id,questionId:q.id,kind:'choice',answer:value,options:q.options.map(o=>tr(o.label)),correct,feedback:tr(option.feedback)};if(window.ZTHProgress9)window.ZTHProgress9.recordAttempt(record);else{const key=id+'/'+q.id,list=localAttempts.get(key)||[];list.push({...record,at:new Date().toISOString()});localAttempts.set(key,list);}feedback.dataset.state=correct?'correct':'incorrect';feedback.textContent=(correct?T('正确。','Correct. '):T('还不正确。','Not yet. '))+tr(option.feedback);updateHistory(root,id,q);},{signal:abort.signal});}
 const oldLesson=lesson4;lesson4=function(){const id=UI4.id;let html=oldLesson();if(!data(id)){if(id==='kirchhoff'||id==='rc'||id==='components'){const ids=id==='kirchhoff'?['divider-foundation']:id==='rc'?['capacitor-foundation','inductor-foundation']:FOUNDATION_LESSON_IDS9;html=html.replace('<nav class="lesson-pagination7"',`<section class="f9-related"><h2>${T('把基础再拆开一步','Explore the foundation in detail')}</h2>${ids.map(x=>`<button data-lesson="${x}">${h(tr(data(x).title))} ↗</button>`).join('')}</section><nav class="lesson-pagination7"`);}return html;}
 const scope=LESSON_GUIDE7[id].labNote,aside=`<aside class="lesson-work4 lesson-work7 f9-work"><div class="lesson-lab-note7"><span class="eyebrow7">${T('本课专用操作台','DEDICATED LESSON WORKBENCH')}</span><p>${h(tr(scope))}</p></div>${render(id)}</aside>`;html=html.replace(/<aside class="lesson-work4 lesson-work7"[\s\S]*?<\/aside>/,'').replace('<article class="reading4">',aside+'<article class="reading4">');html=html.replace(/<button data-lab="[^"]+">[^<]*<\/button>/,`<a href="#foundation9-${id}" data-jump7="foundation9-${id}">${T('跳到本课操作台','Jump to this workbench')} ↓</a>`);return html.replace('<section class="case8"',quizzes(id)+'<section class="case8"');};
 const oldRender=render4;render4=function(){unmount();oldRender();const node=document.querySelector('[data-foundation9]');if(node){mount(node,node.dataset.foundation9);mountQuiz(node.dataset.foundation9);}};
